1	package net.officefloor.hq.app.invoices;
2	
3	import java.math.BigDecimal;
4	import java.time.LocalDate;
5	import java.util.List;
6	import net.officefloor.hq.app.Audit;
7	import org.springframework.jdbc.core.JdbcTemplate;
8	import org.springframework.jdbc.core.RowMapper;
9	import org.springframework.stereotype.Service;
10	import org.springframework.transaction.annotation.Transactional;
11	
12	/**
13	 * Business logic for invoices. Invoices are always viewed in the context of their project, so the
14	 * list is scoped by project id. The derived total the UI shows is computed by the front-end from the
15	 * returned rows; this service just surfaces the project's invoices in a stable order. Marking an
16	 * invoice paid flips its status and records an audit entry so the action can be checked later.
17	 */
18	@Service
19	public class InvoiceService {
20	
21	    // An invoice's amount minus whatever has been paid against it is what is still left to pay.
22	    private static final String DUE_AWARE_SELECT =
23	            "SELECT i.id, i.project_id, i.amount, i.status, i.issued_date, i.due_date, "
24	                    + "i.amount - COALESCE((SELECT SUM(p.amount) FROM payments p "
25	                    + "WHERE p.invoice_id = i.id), 0) AS due_amount FROM invoices i ";
26	
27	    private static final RowMapper<InvoiceView> INVOICE_MAPPER = (rs, i) -> new InvoiceView(
28	            rs.getLong("id"), rs.getLong("project_id"), rs.getBigDecimal("amount"),
29	            rs.getString("status"), rs.getDate("issued_date").toLocalDate().toString(),
30	            rs.getDate("due_date").toLocalDate().toString(), rs.getBigDecimal("due_amount"));
31	
32	    private final InvoiceRepository repository;
33	    private final LineItemRepository lineItemRepository;
34	    private final PaymentRepository paymentRepository;
35	    private final JdbcTemplate jdbc;
36	    private final Audit audit;
37	
38	    public InvoiceService(InvoiceRepository repository, LineItemRepository lineItemRepository,
39	            PaymentRepository paymentRepository, JdbcTemplate jdbc, Audit audit) {
40	        this.repository = repository;
41	        this.lineItemRepository = lineItemRepository;
42	        this.paymentRepository = paymentRepository;
43	        this.jdbc = jdbc;
44	        this.audit = audit;
45	    }
46	
47	    /** Every invoice across all projects; narrowed to a single lifecycle stage when {@code status} is given. */
48	    @Transactional(readOnly = true)
49	    public List<AllInvoiceView> listAll(String status) {
50	        RowMapper<AllInvoiceView> mapper = (rs, i) -> new AllInvoiceView(rs.getLong("id"),
51	                rs.getString("project_name"), rs.getBigDecimal("amount"), rs.getString("status"));
52	        String base = "SELECT i.id, i.amount, i.status, p.name AS project_name "
53	                + "FROM invoices i JOIN projects p ON i.project_id = p.id ";
54	        if (status == null || status.isBlank()) {
55	            return jdbc.query(base + "ORDER BY i.id ASC", mapper);
56	        }
57	        return jdbc.query(base + "WHERE i.status = ? ORDER BY i.id ASC", mapper, status.trim());
58	    }
59	
60	    @Transactional(readOnly = true)
61	    public List<InvoiceView> listForProject(Long projectId) {
62	        return jdbc.query(
63	                DUE_AWARE_SELECT + "WHERE i.project_id = ? ORDER BY i.id ASC",
64	                INVOICE_MAPPER, projectId);
65	    }
66	
67	    @Transactional(readOnly = true)
68	    public List<InvoiceView> listForProjectByDueDate(Long projectId) {
69	        return jdbc.query(
70	                DUE_AWARE_SELECT + "WHERE i.project_id = ? ORDER BY i.due_date ASC, i.id ASC",
71	                INVOICE_MAPPER, projectId);
72	    }
73	
74	    @Transactional
75	    public InvoiceView create(Long projectId, BigDecimal amount) {
76	        if (projectId == null) {
77	            throw new IllegalArgumentException("An invoice requires a project");
78	        }
79	        if (amount == null) {
80	            throw new IllegalArgumentException("An invoice requires an amount");
81	        }
82	        if (amount.signum() <= 0) {
83	            throw new IllegalArgumentException("An invoice amount must be greater than zero");
84	        }
85	        Invoice invoice = new Invoice();
86	        invoice.setProjectId(projectId);
87	        invoice.setAmount(amount);
88	        // A new invoice goes out today and is due 30 days later.
89	        LocalDate issued = LocalDate.now();
90	        invoice.setIssuedDate(issued);
91	        invoice.setDueDate(issued.plusDays(30));
92	        Invoice saved = repository.save(invoice);
93	        // A brand-new invoice has had nothing paid against it yet, so the whole amount is due.
94	        return new InvoiceView(saved.getId(), saved.getProjectId(), saved.getAmount(),
95	                saved.getStatus(), saved.getIssuedDate().toString(), saved.getDueDate().toString(),
96	                saved.getAmount());
97	    }
98	
99	    @Transactional
100	    public InvoiceView send(Long invoiceId) {
101	        if (invoiceId == null) {
102	            throw new IllegalArgumentException("An invoice id is required");
103	        }
104	        InvoiceView current = find(invoiceId);
105	        if (!"DRAFT".equals(current.getStatus())) {
106	            throw new IllegalStateException("Only a draft invoice can be sent");
107	        }
108	        jdbc.update("UPDATE invoices SET status = 'SENT' WHERE id = ?", invoiceId);
109	        InvoiceView invoice = find(invoiceId);
110	        audit.record("INVOICE_SENT id=" + invoice.getId() + " amount="
111	                + invoice.getAmount().setScale(2));
112	        return invoice;
113	    }
114	
115	    @Transactional
116	    public InvoiceView pay(Long invoiceId) {
117	        if (invoiceId == null) {
118	            throw new IllegalArgumentException("An invoice id is required");
119	        }
120	        InvoiceView current = find(invoiceId);
121	        // Payment is only allowed once an invoice has been sent.
122	        if (!"SENT".equals(current.getStatus())) {
123	            throw new IllegalStateException("An invoice can only be paid once it has been sent");
124	        }
125	        jdbc.update("UPDATE invoices SET status = 'PAID' WHERE id = ?", invoiceId);
126	        InvoiceView invoice = find(invoiceId);
127	        audit.record("INVOICE_PAID id=" + invoice.getId() + " amount="
128	                + invoice.getAmount().setScale(2));
129	        return invoice;
130	    }
131	
132	    /** The line items of an invoice, in the order they were added. */
133	    @Transactional(readOnly = true)
134	    public List<LineItemView> listLineItems(Long invoiceId) {
135	        return jdbc.query(
136	                "SELECT id, invoice_id, description, qty, unit_price FROM line_items WHERE invoice_id = ? ORDER BY id ASC",
137	                (rs, i) -> new LineItemView(rs.getLong("id"), rs.getLong("invoice_id"),
138	                        rs.getString("description"), rs.getInt("qty"),
139	                        rs.getBigDecimal("unit_price")),
140	                invoiceId);
141	    }
142	
143	    /**
144	     * Add one line item to an invoice, then re-derive the invoice's amount as the sum of each line's
145	     * quantity times unit price so the stored total stays in step. Returns the invoice's line items.
146	     */
147	    @Transactional
148	    public List<LineItemView> addLineItem(Long invoiceId, NewLineItem body) {
149	        if (invoiceId == null) {
150	            throw new IllegalArgumentException("An invoice id is required");
151	        }
152	        if (body == null || body.getDescription() == null || body.getDescription().isBlank()) {
153	            throw new IllegalArgumentException("A line item requires a description");
154	        }
155	        if (body.getQty() == null || body.getQty() <= 0) {
156	            throw new IllegalArgumentException("A line item requires a quantity greater than zero");
157	        }
158	        if (body.getUnitPrice() == null || body.getUnitPrice().signum() < 0) {
159	            throw new IllegalArgumentException("A line item requires a unit price that is not negative");
160	        }
161	        LineItem lineItem = new LineItem();
162	        lineItem.setInvoiceId(invoiceId);
163	        lineItem.setDescription(body.getDescription());
164	        lineItem.setQty(body.getQty());
165	        lineItem.setUnitPrice(body.getUnitPrice());
166	        lineItemRepository.save(lineItem);
167	        jdbc.update(
168	                "UPDATE invoices SET amount = COALESCE((SELECT SUM(qty * unit_price) FROM line_items WHERE invoice_id = ?), 0) WHERE id = ?",
169	                invoiceId, invoiceId);
170	        return listLineItems(invoiceId);
171	    }
172	
173	    /**
174	     * Remove one line item from an invoice, then re-derive the invoice's amount as the sum of each
175	     * remaining line's quantity times unit price so the stored total stays in step. Returns the
176	     * invoice's remaining line items.
177	     */
178	    @Transactional
179	    public List<LineItemView> removeLineItem(Long invoiceId, Long lineItemId) {
180	        if (invoiceId == null) {
181	            throw new IllegalArgumentException("An invoice id is required");
182	        }
183	        if (lineItemId == null) {
184	            throw new IllegalArgumentException("A line item id is required");
185	        }
186	        jdbc.update("DELETE FROM line_items WHERE id = ? AND invoice_id = ?", lineItemId, invoiceId);
187	        jdbc.update(
188	                "UPDATE invoices SET amount = COALESCE((SELECT SUM(qty * unit_price) FROM line_items WHERE invoice_id = ?), 0) WHERE id = ?",
189	                invoiceId, invoiceId);
190	        return listLineItems(invoiceId);
191	    }
192	
193	    /** The payments a client has made on an invoice, in the order they were recorded. */
194	    @Transactional(readOnly = true)
195	    public List<PaymentView> listPayments(Long invoiceId) {
196	        return jdbc.query(
197	                "SELECT id, invoice_id, amount, paid_date FROM payments WHERE invoice_id = ? ORDER BY id ASC",
198	                (rs, i) -> new PaymentView(rs.getLong("id"), rs.getLong("invoice_id"),
199	                        rs.getBigDecimal("amount"), rs.getDate("paid_date").toLocalDate().toString()),
200	                invoiceId);
201	    }
202	
203	    /** Record one payment a client has made against an invoice. Returns the invoice's payments. */
204	    @Transactional
205	    public List<PaymentView> addPayment(Long invoiceId, NewPayment body) {
206	        if (invoiceId == null) {
207	            throw new IllegalArgumentException("An invoice id is required");
208	        }
209	        if (body == null || body.getAmount() == null || body.getAmount().signum() <= 0) {
210	            throw new IllegalArgumentException("A payment requires an amount greater than zero");
211	        }
212	        if (body.getDate() == null || body.getDate().isBlank()) {
213	            throw new IllegalArgumentException("A payment requires a date");
214	        }
215	        Payment payment = new Payment();
216	        payment.setInvoiceId(invoiceId);
217	        payment.setAmount(body.getAmount());
218	        payment.setPaidDate(LocalDate.parse(body.getDate()));
219	        paymentRepository.save(payment);
220	        audit.record("PAYMENT_RECORDED invoice=" + invoiceId + " amount="
221	                + body.getAmount().setScale(2) + " date=" + body.getDate());
222	        return listPayments(invoiceId);
223	    }
224	
225	    private InvoiceView find(Long invoiceId) {
226	        return jdbc.queryForObject(DUE_AWARE_SELECT + "WHERE i.id = ?", INVOICE_MAPPER, invoiceId);
227	    }
228	}
229

