7	import org.springframework.context.annotation.Profile;
8	import org.springframework.jdbc.core.JdbcTemplate;
9	import org.springframework.web.bind.annotation.PostMapping;
10	import org.springframework.web.bind.annotation.RequestBody;
11	import org.springframework.web.bind.annotation.RequestMapping;
12	import org.springframework.web.bind.annotation.RestController;
13	
14	/**
15	 * Per-spec data setup for the harness (DESIGN.md §9). Profile-guarded so it exists ONLY under the
16	 * harness launch (bin/start sets spring.profiles.active=harness) — never in a real deploy. This is
17	 * APP CODE and EVOLVES with the schema (NOT pinned); a change that breaks a prior spec's seed is a
18	 * seed-path regression. Tests call these to ARRANGE data; they ASSERT only through the UI.
19	 */
20	@Profile("harness")
21	@RestController
22	@RequestMapping("/__test__")
23	public class TestSupportController {
24	
25	    private final Audit audit;
26	    private final JdbcTemplate jdbc;
27	
28	    public TestSupportController(Audit audit, JdbcTemplate jdbc) {
29	        this.audit = audit;
30	        this.jdbc = jdbc;
31	    }
32	
33	    /** Truncate all domain tables and clear the audit file so each spec starts clean. */
34	    @PostMapping("/reset")
35	    public void reset() {
36	        audit.clear();
37	        // Disable FK checks so a referenced parent (clients) can be truncated alongside its child.
38	        jdbc.execute("SET REFERENTIAL_INTEGRITY FALSE");
39	        jdbc.execute("TRUNCATE TABLE payments RESTART IDENTITY");
40	        jdbc.execute("TRUNCATE TABLE line_items RESTART IDENTITY");
41	        jdbc.execute("TRUNCATE TABLE invoices RESTART IDENTITY");
42	        jdbc.execute("TRUNCATE TABLE contacts RESTART IDENTITY");
43	        jdbc.execute("TRUNCATE TABLE tasks RESTART IDENTITY");
44	        jdbc.execute("TRUNCATE TABLE notes RESTART IDENTITY");
45	        jdbc.execute("TRUNCATE TABLE project_tags RESTART IDENTITY");
46	        jdbc.execute("TRUNCATE TABLE tags RESTART IDENTITY");
47	        jdbc.execute("TRUNCATE TABLE projects RESTART IDENTITY");
48	        jdbc.execute("TRUNCATE TABLE clients RESTART IDENTITY");
49	        jdbc.execute("SET REFERENTIAL_INTEGRITY TRUE");
50	    }
51	
52	    /** Insert the fixture a spec needs; the payload shape evolves with the schema. */
53	    @PostMapping("/seed")
54	    @SuppressWarnings("unchecked")
55	    public void seed(@RequestBody Map<String, Object> fixture) {
56	        List<Map<String, Object>> clients =
57	                (List<Map<String, Object>>) fixture.getOrDefault("clients", List.of());
58	        long maxClientId = 0;
59	        for (Map<String, Object> client : clients) {
60	            long id = ((Number) client.get("id")).longValue();
61	            // Seed with the fixture's explicit id (JdbcTemplate, not JPA) so specs can assert by id.
62	            jdbc.update("INSERT INTO clients (id, name, email) VALUES (?, ?, ?)",
63	                    id, client.get("name"), client.get("email"));
64	            maxClientId = Math.max(maxClientId, id);
65	        }
66	        if (maxClientId > 0) {
67	            // Advance the identity so app-generated ids don't collide with seeded rows.
68	            jdbc.execute("ALTER TABLE clients ALTER COLUMN id RESTART WITH " + (maxClientId + 1));
69	        }
70	
71	        List<Map<String, Object>> projects =
72	                (List<Map<String, Object>>) fixture.getOrDefault("projects", List.of());
73	        long maxProjectId = 0;
74	        for (Map<String, Object> project : projects) {
75	            long id = ((Number) project.get("id")).longValue();
76	            long clientId = ((Number) project.get("clientId")).longValue();
77	            jdbc.update("INSERT INTO projects (id, name, client_id) VALUES (?, ?, ?)",
78	                    id, project.get("name"), clientId);
79	            maxProjectId = Math.max(maxProjectId, id);
80	        }
81	        if (maxProjectId > 0) {
82	            jdbc.execute("ALTER TABLE projects ALTER COLUMN id RESTART WITH " + (maxProjectId + 1));
83	        }
84	
85	        List<Map<String, Object>> contacts =
86	                (List<Map<String, Object>>) fixture.getOrDefault("contacts", List.of());
87	        long maxContactId = 0;
88	        for (Map<String, Object> contact : contacts) {
89	            long id = ((Number) contact.get("id")).longValue();
90	            long clientId = ((Number) contact.get("clientId")).longValue();
91	            jdbc.update("INSERT INTO contacts (id, client_id, name, email, role) VALUES (?, ?, ?, ?, ?)",
92	                    id, clientId, contact.get("name"), contact.get("email"), contact.get("role"));
93	            maxContactId = Math.max(maxContactId, id);
94	        }
95	        if (maxContactId > 0) {
96	            jdbc.execute("ALTER TABLE contacts ALTER COLUMN id RESTART WITH " + (maxContactId + 1));
97	        }
98	
99	        List<Map<String, Object>> tasks =
100	                (List<Map<String, Object>>) fixture.getOrDefault("tasks", List.of());
101	        long maxTaskId = 0;
102	        for (Map<String, Object> task : tasks) {
103	            long id = ((Number) task.get("id")).longValue();
